"use client";

import { memo, type ComponentProps } from "react";
import { Check } from "lucide-react";
import { cn } from "cn";
import { BracketCard } from "../components/bracket-card";
import { Button } from "../components/button";

export const PricingBracket = memo(function PricingBracket({
  title = "Plans with room to grow",
  description = "A focused set of plans for independent builders and teams.",
  className,
  ...props
}: Omit<ComponentProps<"section">, "title"> & {
  title?: string;
  description?: string;
} = {}) {
  const plans = [
    { name: "Builder", price: "$12", features: ["Unlimited drafts", "Core blocks"] },
    { name: "Studio", price: "$32", features: ["Unlimited projects", "Priority support"] },
  ];

  return (
    <section {...props} className={cn("@container w-full space-y-8", className)}>
      <header className="text-center">
        <h2 className="typography-section-title">{title}</h2>
        <p className="mt-3 typography-body">{description}</p>
      </header>
      <div className="grid gap-4 @lg:grid-cols-2">
        {plans.map((plan) => (
          <BracketCard key={plan.name}>
            <h3 className="typography-subsection-title">{plan.name}</h3>
            <p className="mt-4 text-4xl font-semibold">
              {plan.price}
              <span className="text-sm text-muted-foreground"> / month</span>
            </p>
            <ul className="mt-6 space-y-3 text-sm">
              {plan.features.map((feature) => (
                <li key={feature} className="flex gap-2">
                  <Check size={16} className="mt-0.5 text-secondary dark:text-primary" aria-hidden="true" />
                  {feature}
                </li>
              ))}
            </ul>
            <Button href="/signup" variant="outline" className="mt-8 w-full">
              Choose {plan.name}
            </Button>
          </BracketCard>
        ))}
      </div>
    </section>
  );
});

import { memo, type ComponentProps } from "react";
import { cn } from "cn";
import { Card } from "./card";

interface BracketCardProps extends ComponentProps<"div"> {
  variant?: "brackets" | "corners";
}

export const BracketCard = memo(function BracketCard({
  children,
  className,
  variant = "brackets",
  ...props
}: BracketCardProps = {}) {
  return (
    <div
      data-slot="bracket-card"
      className={cn("relative min-w-0 w-full p-2", className)}
      {...props}
    >
      <div aria-hidden="true" className="pointer-events-none absolute inset-0 text-foreground/70">
        <>
          <span
            className={cn(
              "absolute left-0 top-0 border-l border-t border-current",
              variant === "corners" ? "size-8" : "size-6 border-l-2 border-t-2",
            )}
          />
          <span
            className={cn(
              "absolute right-0 top-0 border-r border-t border-current",
              variant === "corners" ? "size-8" : "size-6 border-r-2 border-t-2",
            )}
          />
          <span
            className={cn(
              "absolute bottom-0 left-0 border-b border-l border-current",
              variant === "corners" ? "size-8" : "size-6 border-b-2 border-l-2",
            )}
          />
          <span
            className={cn(
              "absolute bottom-0 right-0 border-b border-r border-current",
              variant === "corners" ? "size-8" : "size-6 border-b-2 border-r-2",
            )}
          />
        </>
      </div>
      <Card
        title=""
        description=""
        className={cn(
          "w-full! max-w-none! bg-background! p-6! sm:p-8!",
          variant === "brackets" ? "border-dashed" : "border-transparent!",
        )}
      >
        {children}
      </Card>
    </div>
  );
});

import { memo, type ComponentProps } from "react";

type ButtonProps = {
  variant?: "primary" | "secondary" | "ghost" | "destructive" | "outline";
} & ((ComponentProps<"button"> & { href?: never }) | (ComponentProps<"a"> & { href: string }));

export function buttonClassName(variant: ButtonProps["variant"] = "primary", className = "") {
  const styles = {
    primary:
      "[--button-color:var(--color-emerald-400)] [--button-top:var(--color-emerald-300)] [--button-stroke-top:var(--color-emerald-200)] [--button-stroke-bottom:var(--color-emerald-700)] text-neutral-950",
    secondary: "[--button-color:var(--secondary)] text-secondary-foreground",
    ghost: "bg-transparent text-foreground hover:bg-muted",
    destructive: "[--button-color:var(--destructive)] text-destructive-foreground",
    outline:
      "[--button-color:var(--background)] [--button-top:var(--background)] [--button-bottom:var(--muted)] [--button-stroke-top:var(--border)] [--button-stroke-bottom:color-mix(in_srgb,var(--foreground)_25%,var(--border))] text-foreground hover:[--button-top:var(--muted)]",
  };
  const surface =
    variant === "ghost"
      ? ""
      : "border border-transparent [background:linear-gradient(to_bottom,var(--button-top,color-mix(in_srgb,var(--button-color)_88%,white)),var(--button-bottom,var(--button-color)))_padding-box,linear-gradient(to_bottom,var(--button-stroke-top,color-mix(in_srgb,var(--button-color)_65%,white)),var(--button-stroke-bottom,color-mix(in_srgb,var(--button-color)_65%,black)))_border-box] shadow-[0_1px_2px_rgb(0_0_0/0.12),0_4px_8px_-2px_rgb(0_0_0/0.18)] hover:[--button-top:color-mix(in_srgb,var(--button-color)_78%,white)]";
  return `inline-flex min-h-11 items-center justify-center gap-2 rounded-lg px-5 py-2 text-sm font-semibold  transition-colors focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-50 ${surface} ${styles[variant] ?? styles.primary} ${className}`;
}

export const Button = memo(function Button({
  children = "Get started",
  variant = "primary",
  className = "",
  ...props
}: ButtonProps = {}) {
  const classes = buttonClassName(variant, className);

  if (props.href !== undefined) {
    return (
      <a className={classes} {...props}>
        {children}
      </a>
    );
  }

  return (
    <button type="button" className={classes} {...props}>
      {children}
    </button>
  );
});
